from copy import deepcopy


_STATUSES = {"draft", "queued", "dispatch", "inspection", "closed"}


def advance_shipments(shipments):
    if isinstance(shipments, (str, bytes)):
        raise TypeError("shipments must be an iterable")
    try:
        items = list(shipments)
    except TypeError as exc:
        raise TypeError("shipments must be iterable") from exc

    for item in items:
        if not isinstance(item, dict):
            raise TypeError("each shipment must be a dictionary")
        if set(item) != {"status", "packages", "holds"}:
            raise ValueError("invalid shipment fields")
        if item["status"] not in _STATUSES:
            raise ValueError("invalid status")
        for field in ("packages", "holds"):
            value = item[field]
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError(f"{field} must be an integer")
            if value < 0:
                raise ValueError(f"{field} must be non-negative")

    result = deepcopy(items)
    for item in result:
        status = item["status"]
        packages = item["packages"]
        holds = item["holds"]
        if status == "draft":
            item["status"] = "closed" if packages == 0 else "queued"
        elif status == "queued" and holds == 0:
            item["status"] = "dispatch" if packages > 2 else "inspection"
        elif status == "dispatch" and holds > 0:
            item["status"] = "inspection"
        elif status == "inspection" and holds == 0:
            item["status"] = "closed"
    return result

